<?php

declare(strict_types=1);
use App\Core\Session;
?>
<?php if ($errors === []): ?><div class="row row-deck g-3 mb-4"><?php foreach (['total'=>'All orders','pending'=>'Pending','active'=>'In progress'] as $key=>$label): ?><div class="col-sm-4"><div class="card"><div class="card-body"><h2 class="subheader"><?= e($label) ?></h2><div class="h1 mb-0"><?= e((string)($counts[$key] ?? 0)) ?></div></div></div></div><?php endforeach; ?></div><?php endif; ?>
<div class="card mb-3"><div class="card-body"><form method="get" action="<?= e(url('/admin/orders')) ?>" class="row g-3 align-items-end">
<div class="col-md-4"><label for="q" class="form-label">Order number or customer</label><input id="q" name="q" class="form-control" maxlength="100" value="<?= e($filters['q']) ?>"></div>
<div class="col-md-3"><label for="date" class="form-label">Order date</label><input type="date" id="date" name="date" class="form-control" value="<?= e($filters['date']) ?>"></div>
<div class="col-md-3"><label for="status" class="form-label">Status</label><select id="status" name="status" class="form-select"><option value="">All statuses</option><?php foreach ($statuses as $status): ?><option value="<?= e($status) ?>" <?= $filters['status'] === $status ? 'selected' : '' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><button class="btn btn-primary">Filter</button> <a href="<?= e(url('/admin/orders')) ?>">Clear</a></div></form></div></div>
<?php if ($errors !== []): ?><div class="alert alert-danger" role="alert"><?= e(implode(' ', $errors)) ?></div><?php endif; ?>
<div class="card"><?php if ($orders === []): ?><div class="empty"><h2 class="empty-title">No orders found</h2><p class="empty-subtitle text-secondary">Orders will appear here when customers can place them. Adjust filters to broaden your search.</p></div><?php else: ?>
<div class="table-responsive"><table class="table table-vcenter card-table"><caption class="visually-hidden">Orders</caption><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach ($orders as $order): ?><tr><td><?= e($order['order_no']) ?></td><td><?= e($order['customer']) ?><small class="d-block text-secondary"><?= e($order['email']) ?></small></td><td><?= e($order['created_at']) ?></td><td><?= e($order['subtotal']) ?></td><td><?= e(match ($order['payment_method']) { 'cod' => 'Cash on delivery', 'bank' => 'Bank transfer', default => 'Not recorded' }) ?></td><td><span class="badge bg-secondary-lt"><?= e(ucfirst($order['status'])) ?></span></td><td><details><summary class="btn btn-sm">Details and actions</summary><div class="p-3 order-details"><h3 class="h4">Delivery</h3><p><?= e($order['delivery_name']) ?><br><?= e($order['delivery_phone']) ?><br><?= nl2br(e($order['delivery_address'])) ?><br><?= e($order['city'] ?: 'City not recorded') ?></p><?php if ($order['notes']): ?><p>Notes: <?= nl2br(e($order['notes'])) ?></p><?php endif; ?><h3 class="h4">Items</h3><?php if ($order['items'] === []): ?><p>No items recorded.</p><?php else: ?><ul><?php foreach ($order['items'] as $item): ?><li><?= e($item['fabric_title']) ?> (<?= e($item['product_code']) ?>), <?= e(! empty($item['color_name']) ? $item['color_name'] : 'Colour not selected') ?><?= ! empty($item['unit']) ? ' / ' . e($item['unit']) : '' ?> — <?= e($item['quantity']) ?> × <?= e($item['unit_price']) ?> = <?= e($item['line_total']) ?></li><?php endforeach; ?></ul><?php endif; ?><h3 class="h4">Status history</h3><?php if ($order['history'] === []): ?><p>No status changes recorded.</p><?php else: ?><ul><?php foreach ($order['history'] as $entry): ?><li><?= e($entry['changed_at']) ?>: <?= e($entry['old_status']) ?> → <?= e($entry['new_status']) ?> by <?= e($entry['admin_name']) ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if ($order['next'] !== []): ?><form method="post" action="<?= e(url('/admin/orders/status')) ?>" onsubmit="return confirm('Confirm this order status change?')"><input type="hidden" name="_token" value="<?= e(Session::csrfToken()) ?>"><input type="hidden" name="id" value="<?= e($order['id']) ?>"><input type="hidden" name="expected" value="<?= e($order['status']) ?>"><label class="form-label" for="status-<?= e($order['id']) ?>">Change status</label><select class="form-select mb-2" id="status-<?= e($order['id']) ?>" name="status"><?php foreach ($order['next'] as $next): ?><option value="<?= e($next) ?>"><?= e(ucfirst($next)) ?></option><?php endforeach; ?></select><button class="btn btn-primary btn-sm">Update status</button></form><?php endif; ?></div></details></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php $query = $filters; ?><nav class="d-flex gap-3 mt-3" aria-label="Order pages"><?php if ($page > 1): $query['page']=$page-1; ?><a class="btn" href="<?= e(url('/admin/orders') . '?' . http_build_query($query)) ?>">Previous</a><?php endif; ?><span>Page <?= e($page) ?></span><?php if ($hasNext): $query['page']=$page+1; ?><a class="btn" href="<?= e(url('/admin/orders') . '?' . http_build_query($query)) ?>">Next</a><?php endif; ?></nav>
